DROP DATABASE IF EXISTS Tienda_Moda;
CREATE DATABASE Tienda_Moda;
USE Tienda_Moda;

SET SQL_SAFE_UPDATES = 0;
SET GLOBAL log_bin_trust_function_creators = 1;

CREATE TABLE Usuarios(
ID INT PRIMARY KEY AUTO_INCREMENT,
Nombre VARCHAR(50) NOT NULL,
Apellidos VARCHAR(80),
Correo VARCHAR(100) UNIQUE NOT NULL,
Contrasena VARCHAR(100) NOT NULL,
Telefono VARCHAR(20),
Direccion VARCHAR(150),
Ciudad VARCHAR(50),
Codigo_postal VARCHAR(10),
Fecha_registro DATE DEFAULT (CURRENT_DATE),
Rol ENUM('CLIENTE', 'GESTOR_PEDIDOS', 'ADMIN') DEFAULT 'CLIENTE',
Activo BOOLEAN DEFAULT TRUE
);

CREATE TABLE Categorias(
Codigo VARCHAR(10) PRIMARY KEY,
Nombre VARCHAR(50) UNIQUE NOT NULL,
Tipo_producto ENUM('ROPA', 'CALZADO', 'ACCESORIO', 'OTRO') NOT NULL,
Publico ENUM('HOMBRE', 'MUJER', 'INFANTIL', 'UNISEX') DEFAULT 'UNISEX',
Temporada ENUM('PRIMAVERA', 'VERANO', 'OTONO', 'INVIERNO', 'TODO EL AÑO') DEFAULT 'TODO EL AÑO',
Activa BOOLEAN DEFAULT TRUE
);

CREATE TABLE Ofertas(
Codigo VARCHAR(20) PRIMARY KEY,
Nombre VARCHAR(80) NOT NULL,
Porcentaje_descuento INT NOT NULL,
Fecha_inicio DATE NOT NULL,
Fecha_fin DATE NOT NULL,
Activa BOOLEAN DEFAULT TRUE,
CHECK (Porcentaje_descuento >= 0 AND Porcentaje_descuento <= 100)
);

CREATE TABLE Productos(
Referencia VARCHAR(20) PRIMARY KEY,
Categoria VARCHAR(10) NOT NULL,
Oferta VARCHAR(20),
Nombre VARCHAR(100) NOT NULL,
Marca VARCHAR(50),
Descripcion VARCHAR(200),
Talla VARCHAR(10),
Color VARCHAR(30),
Precio DECIMAL(7,2) NOT NULL,
Stock INT NOT NULL,
Estado ENUM('DISPONIBLE', 'AGOTADO', 'OCULTO', 'DESCATALOGADO') DEFAULT 'DISPONIBLE',

FOREIGN KEY (Categoria) REFERENCES Categorias(Codigo),
FOREIGN KEY (Oferta) REFERENCES Ofertas(Codigo) ON DELETE SET NULL,

CHECK (Precio >= 0),
CHECK (Stock >= 0)
);

CREATE TABLE Carritos(
Codigo VARCHAR(30) PRIMARY KEY,
Usuario INT NULL,
Token_Invitado VARCHAR(100),
Tipo_Carrito ENUM('REGISTRADO', 'INVITADO') NOT NULL,
Fecha_creacion DATETIME DEFAULT CURRENT_TIMESTAMP,
Fecha_ultima_actualizacion DATETIME DEFAULT CURRENT_TIMESTAMP,
Expira_en DATETIME NULL,
Estado ENUM('ACTIVO', 'CONVERTIDO', 'ABANDONADO') DEFAULT 'ACTIVO',

FOREIGN KEY (Usuario) REFERENCES Usuarios(ID),

UNIQUE(Token_Invitado),

CHECK (
    (Tipo_Carrito = 'REGISTRADO' AND Usuario IS NOT NULL AND Token_Invitado IS NULL)
    OR
    (Tipo_Carrito = 'INVITADO' AND Usuario IS NULL AND Token_Invitado IS NOT NULL)
)
);

CREATE TABLE Detalles_Carrito(
Carrito VARCHAR(30) NOT NULL,
Producto VARCHAR(20) NOT NULL,
Cantidad INT NOT NULL,
Fecha_agregado DATETIME DEFAULT CURRENT_TIMESTAMP,

PRIMARY KEY (Carrito, Producto),

FOREIGN KEY (Carrito) REFERENCES Carritos(Codigo) ON DELETE CASCADE,
FOREIGN KEY (Producto) REFERENCES Productos(Referencia),

CHECK (Cantidad > 0)
);

CREATE TABLE Pedidos(
Codigo VARCHAR(20) PRIMARY KEY,
Usuario INT NULL,
Gestor INT NULL,
Tipo_Compra ENUM('REGISTRADO', 'INVITADO') NOT NULL,
Nombre_Comprador VARCHAR(80),
Correo_Comprador VARCHAR(100),
Telefono_Comprador VARCHAR(20),
Direccion_Envio VARCHAR(150) NOT NULL,
Fecha_pedido DATETIME DEFAULT CURRENT_TIMESTAMP,
Estado ENUM('PENDIENTE', 'PREPARANDO', 'ENVIADO', 'ENTREGADO', 'CANCELADO') DEFAULT 'PENDIENTE',
Metodo_pago ENUM('TARJETA', 'PAYPAL', 'BIZUM', 'TRANSFERENCIA') NOT NULL,
Tipo_envio ENUM('NORMAL', 'URGENTE', 'RECOGIDA_TIENDA') DEFAULT 'NORMAL',
Gastos_envio DECIMAL(6,2) DEFAULT 0,
Total DECIMAL(8,2) DEFAULT 0,

FOREIGN KEY (Usuario) REFERENCES Usuarios(ID),
FOREIGN KEY (Gestor) REFERENCES Usuarios(ID),

CHECK (
    (Tipo_Compra = 'REGISTRADO' AND Usuario IS NOT NULL)
    OR
    (Tipo_Compra = 'INVITADO' AND Usuario IS NULL AND Nombre_Comprador IS NOT NULL AND Correo_Comprador IS NOT NULL)
),

CHECK (Gastos_envio >= 0),
CHECK (Total >= 0)
);

CREATE TABLE Detalles_Pedido(
Pedido VARCHAR(20) NOT NULL,
Producto VARCHAR(20) NOT NULL,
Cantidad INT NOT NULL,
Precio_unitario DECIMAL(7,2) NOT NULL,
Porcentaje_descuento INT DEFAULT 0,
Subtotal DECIMAL(8,2) NOT NULL,

PRIMARY KEY (Pedido, Producto),

FOREIGN KEY (Pedido) REFERENCES Pedidos(Codigo) ON DELETE CASCADE,
FOREIGN KEY (Producto) REFERENCES Productos(Referencia),

CHECK (Cantidad > 0),
CHECK (Precio_unitario >= 0),
CHECK (Porcentaje_descuento >= 0 AND Porcentaje_descuento <= 100),
CHECK (Subtotal >= 0)
);



